/**
 * Friends Basic API 测试
 */

import { SynapseEnhancedClient } from "../index.ts";
import { loadTestConfig } from "./config.ts";
import { logger } from "../../logger.ts";

const log = logger.getChild("enhanced:test:friends-basic-api");

interface TestResult {
    name: string;
    passed: boolean;
    responseTime: number;
    error?: string;
    response?: any;
}

export class FriendsBasicApiTests {
    private client: SynapseEnhancedClient;
    private config: ReturnType<typeof loadTestConfig>;

    public constructor() {
        this.config = loadTestConfig();
        this.client = new SynapseEnhancedClient({
            baseUrl: this.config.server.baseUrl,
            accessToken: this.config.server.accessToken,
            apiPrefix: this.config.server.apiPrefix,
            timeout: this.config.test.timeout,
        });
    }

    public async runAllTests(): Promise<TestResult[]> {
        log.info("");
        log.info("=============================");
        log.info("Running Friends Basic API Tests...");
        log.info("=============================");

        const results: TestResult[] = [];

        results.push(await this.testGetFriends());
        results.push(await this.testGetFriend());
        results.push(await this.testCheckFriendship());
        results.push(await this.testSetRemark());

        this.printResults(results);
        return results;
    }

    private printResults(results: TestResult[]): void {
        for (const result of results) {
            const icon = result.passed ? "✓" : "✗";
            log.info(`${icon} ${result.name}: ${result.passed ? "PASSED" : "FAILED"} (${result.responseTime}ms)`);
            if (result.error) {
                log.error(`  Error: ${result.error}`);
            }
        }
        const passed = results.filter((r) => r.passed).length;
        log.info("");
        log.info(`Friends Basic API Results: ${passed}/${results.length} passed`);
    }

    private async testGetFriends(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const result = await this.client.friends.getFriends({ page: 1, limit: 10 });

            return {
                name: "Get Friends",
                passed: Array.isArray(result),
                responseTime: Date.now() - startTime,
                response: { count: result.length },
            };
        } catch (error: any) {
            return {
                name: "Get Friends",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetFriend(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const friend = await this.client.friends.getFriendDetail("@test:example.com");

            return {
                name: "Get Friend Detail",
                passed: friend !== null,
                responseTime: Date.now() - startTime,
                response: { found: friend !== null },
            };
        } catch (error: any) {
            return {
                name: "Get Friend Detail",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testCheckFriendship(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const isFriend = await this.client.friends.isFriend("@test:example.com");

            return {
                name: "Check Friendship",
                passed: typeof isFriend === "boolean",
                responseTime: Date.now() - startTime,
                response: { isFriend },
            };
        } catch (error: any) {
            return {
                name: "Check Friendship",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testSetRemark(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const result = await this.client.friends.setRemark("@test:example.com", "Test Remark");

            return {
                name: "Set Remark",
                passed: typeof result === "boolean",
                responseTime: Date.now() - startTime,
                response: { success: result },
            };
        } catch (error: any) {
            return {
                name: "Set Remark",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }
}

const tests = new FriendsBasicApiTests();
tests.runAllTests().catch((error) => log.error(error));
